Example using `std::set` (similar principles apply to other containers):

```c++
#include <set>
#include <iostream>
#include <algorithm>

template<typename T> 
struct MyAllocator {
  T* allocate(size_t n) { std::cout << "Allocating..."; return new T[n]; }
  void deallocate(T* p, size_t n) { std::cout << "Deallocating..."; delete[] p; }
};

int main() {
  std::set<int, std::less<int>, MyAllocator<int>> s1 = {1, 2, 3};
  std::set<int, std::less<int>, MyAllocator<int>> s2 = s1; // Copy constructor
  std::set<int, std::less<int>, MyAllocator<int>> s3 = std::move(s1); // Move constructor
  return 0;
}
```

code_example:
#include <iostream>
#include <set>
#include <vector>
struct MyData { std::vector<int> data; };
int main() {
  std::set<MyData> s1; //default allocator
  std::set<MyData> s2 = s1; //copy constructor with default allocator
  std::set<MyData> s3 = std::move(s1); //move constructor with default allocator
  std::cout << "Size of s2: " << s2.size() << std::endl;
  std::cout << "Size of s3: " << s3.size() << std::endl;
  return 0;
}
